// An explicit month calendar works consistently without native type=month UI.
const monthPicker=$('monthPicker');let pickerTarget='from',pickerYear=2026;
const monthNames=['January','February','March','April','May','June','July','August','September','October','November','December'];
function updateDateButtons(){for(const id of ['from','to']){const button=$(id+'Calendar');button.textContent=$(id).value?pretty($(id).value)+' ▦':'Select month ▦';button.disabled=$(id).disabled;button.setAttribute('aria-invalid',$(id).getAttribute('aria-invalid')||'false');button.setAttribute('aria-describedby','rangeError');button.setAttribute('aria-label',(id==='from'?'Start':'End')+' month calendar: '+($(id).value?pretty($(id).value):'choose month'))}}
function drawMonthPicker(){const input=$(pickerTarget),min=input.min,max=input.max;const yearSelect=$('pickerYear');yearSelect.replaceChildren();for(let y=+min.slice(0,4);y<=+max.slice(0,4);y++){const option=document.createElement('option');option.value=y;option.textContent=y;yearSelect.append(option)}yearSelect.value=pickerYear;$('pickerHeading').textContent=(pickerTarget==='from'?'Start':'End')+' month';$('pickerPrevious').disabled=pickerYear<=+min.slice(0,4);$('pickerNext').disabled=pickerYear>=+max.slice(0,4);$('pickerMonths').replaceChildren();monthNames.forEach((name,i)=>{const month=pickerYear+'-'+String(i+1).padStart(2,'0');const b=document.createElement('button');b.textContent=name.slice(0,3);b.type='button';b.setAttribute('aria-label',name+' '+pickerYear);b.setAttribute('aria-pressed',String(input.value===month));b.disabled=month<min||month>max;b.onclick=()=>{input.value=month;input.dispatchEvent(new Event('change',{bubbles:true}));updateDateButtons();monthPicker.close();$(pickerTarget+'Calendar').focus()};$('pickerMonths').append(b)})}
for(const id of ['from','to'])$(id+'Calendar').onclick=()=>{pickerTarget=id;const value=$(id).value||$(id).max;pickerYear=+value.slice(0,4);drawMonthPicker();monthPicker.showModal()};$('pickerPrevious').onclick=()=>{pickerYear--;drawMonthPicker()};$('pickerNext').onclick=()=>{pickerYear++;drawMonthPicker()};$('pickerYear').onchange=()=>{pickerYear=+$('pickerYear').value;drawMonthPicker()};window.addEventListener('materialdesk:context',updateDateButtons);updateDateButtons();
